  8101  unsigned
  8102  PackLinuxElf32::elf_get_offset_from_Phdrs(unsigned addr, Elf32_Phdr const *phdr0) const
  8103  {
  8104      Elf32_Phdr const *phdr = phdr0;
  8105      int j = e_phnum;
  8106      for (; --j>=0; ++phdr) if (is_LOAD(phdr)) {
  8107          unsigned const t = addr - get_te32(&phdr->p_vaddr);
  8108          if (t < get_te32(&phdr->p_filesz)) {
  8109              unsigned const p_offset = get_te32(&phdr->p_offset);
  8110              if (file_size_u <= p_offset) { // FIXME: weak
  8111                  char msg[40]; snprintf(msg, sizeof(msg),
  8112                      "bad Elf32_Phdr[%d].p_offset %x",
  8113                      -1+ e_phnum - j, p_offset);
  8114                  throwCantPack(msg);
  8115              }
  8116              return t + p_offset;
  8117          }
  8118      }
  8119      return 0;
  8120  }
