  8122  u32_t  // returns .p_offset
  8123  PackLinuxElf32::check_pt_load(Elf32_Phdr const *const phdr)
  8124  {
  8125      u32_t filesz = get_te32(&phdr->p_filesz);
  8126      u32_t offset = get_te32(&phdr->p_offset), offend = filesz + offset;
  8127      u32_t vaddr  = get_te32(&phdr->p_vaddr);
  8128      u32_t paddr  = get_te32(&phdr->p_paddr);
  8129      u32_t align  = get_te32(&phdr->p_align);
  8130
  8131      if ((-1+ align) & (paddr ^ vaddr)
  8132      ||  file_size_u32 <= (u32_t)offset
  8133      ||  file_size_u32 <  (u32_t)offend
  8134      ||  file_size_u32 <  (u32_t)filesz) {
  8135          char msg[50]; snprintf(msg, sizeof(msg), "bad PT_LOAD phdr[%u]",
  8136              (unsigned)(phdr - phdri));
  8137          throwCantPack(msg);
  8138      }
  8139      return offset;
  8140  }
