  8153  unsigned  // checked .p_offset; sz_dynseg set
  8154  PackLinuxElf32::check_pt_dynamic(Elf32_Phdr const *const phdr)
  8155  {
  8156      unsigned t = get_te32(&phdr->p_offset), s = sizeof(Elf32_Dyn) + t;
  8157      unsigned vaddr = get_te32(&phdr->p_vaddr);
  8158      unsigned filesz = get_te32(&phdr->p_filesz), memsz = get_te32(&phdr->p_memsz);
  8159      unsigned align = get_te32(&phdr->p_align);
  8160      if (file_size_u < t || s < t
  8161      ||  file_size_u < filesz
  8162      ||  file_size_u < (filesz + t)
  8163      ||  t < (e_phnum*sizeof(Elf32_Phdr) + sizeof(Elf32_Ehdr))
  8164      ||  (3 & t) || (7 & (filesz | memsz))  // .balign 4; 8==sizeof(Elf32_Dyn)
  8165      ||  (-1+ align) & (t ^ vaddr)
  8166      ||  file_size_u <= memsz
  8167      ||  filesz < sizeof(Elf32_Dyn)
  8168      ||  memsz  < sizeof(Elf32_Dyn)
  8169      ||  filesz < memsz) {
  8170          char msg[50]; snprintf(msg, sizeof(msg), "bad PT_DYNAMIC phdr[%u]",
  8171              (unsigned)(phdr - phdri));
  8172          throwCantPack(msg);
  8173      }
  8174      sz_dynseg = memsz;
  8175      return t;
